let story=null;
function freshStory(){return {version:1,chapter:0,phase:'explore',name:'Саша',avatar:1,mom:50,dad:50,agency:35,seen:[],inventory:[],route:null,decisions:[]}}
function loadStory(){try{let x=JSON.parse(localStorage.getItem(STORY_KEY)||'null');return x&&x.version===1?x:null}catch{return null}}
function persistStory(){localStorage.setItem(STORY_KEY,JSON.stringify(story));renderGameHub()}
function clamp(v){return Math.max(5,Math.min(95,v))}
function renderGameHub(){let s=loadStory(),done=s?s.chapter:0;document.querySelector('#hubProgress').style.width=(done/8*100)+'%';document.querySelector('#hubProgressText').textContent=s?(s.phase==='ending'?'История пройдена · можно прожить другой путь':(done+1)+' глава из 8 · прогресс сохранён'):'Восемь глав, три маршрута и отношения, которые меняются';document.querySelector('#startGame').textContent=s?(s.phase==='ending'?'Начать другую историю →':'Продолжить историю →'):'Создать героя →'}
function showHub(){document.querySelector('#gamePlay').hidden=true;document.querySelector('#gamesHub').hidden=false;renderGameHub()}
function gameFrame(){document.querySelector('#gamesHub').hidden=true;let root=document.querySelector('#gamePlay');root.hidden=false;root.replaceChildren();let top=document.createElement('div');top.className='story-top';let back=document.createElement('button');back.textContent='← К играм';back.onclick=showHub;let label=document.createElement('span');label.textContent='ТИХИЙ ГОРОД · СВОЯ ДОРОГА';top.append(back,label);root.append(top);return root}
function showIntro(){let root=gameFrame(),wrap=document.createElement('div');wrap.className='story-intro';wrap.innerHTML='<span class="eyebrow">Интерактивная история</span><h2>У каждого есть своя дорога</h2><p>Ты играешь за взрослого героя. В течение недели ему предстоит решить, принять ли предложение о работе, и найти способ говорить с мамой и папой. Исследуй предметы в сценах, выбирай действия и смотри, как меняются отношения. Здесь нет правильной концовки.</p>';let setup=document.createElement('div');setup.className='hero-setup';let label=document.createElement('label');label.htmlFor='heroName';label.textContent='Как зовут героя?';let input=document.createElement('input');input.id='heroName';input.maxLength=20;input.value='Саша';let avatarLabel=document.createElement('label');avatarLabel.textContent='Выбери героя';let avatars=document.createElement('div');avatars.className='avatars';let selected=1;[1,2,3].forEach(n=>{let b=document.createElement('button');b.type='button';b.className='avatar-choice'+(n===1?' selected':'');b.dataset.avatar=n;b.innerHTML='<span class="mini-face"></span><small>Образ '+n+'</small>';b.onclick=()=>{selected=n;avatars.querySelectorAll('button').forEach(x=>x.classList.toggle('selected',x===b))};avatars.append(b)});let start=document.createElement('button');start.className='primary';start.textContent='Начать игру →';start.onclick=()=>{story=freshStory();story.name=input.value.trim().slice(0,20)||'Саша';story.avatar=selected;persistStory();renderScene()};setup.append(label,input,start);wrap.append(setup);root.append(wrap)}
function character(type){let node=document.createElement('div');node.className='character '+type+(type==='hero'?' avatar'+story.avatar:'');node.innerHTML='<span class="body"></span><span class="head"></span>';let name=document.createElement('span');name.className='character-name';name.textContent=type==='hero'?story.name:type==='mom'?'Мама':type==='dad'?'Папа':'Ника';node.append(name);return node}
function say(container,who,text,player=false){let row=document.createElement('div');row.className='dialogue'+(player?' player':'');let avatar=document.createElement('span');avatar.className='speaker';avatar.textContent=who==='Рассказчик'?'✦':who.slice(0,1).toUpperCase();let p=document.createElement('p');p.textContent=text;if(player)row.append(p,avatar);else row.append(avatar,p);container.append(row)}
function relationCard(){let side=document.createElement('div');side.className='story-side';let card=document.createElement('div');card.className='card';let h=document.createElement('h3');h.textContent='Отношения в истории';card.append(h);[['С мамой','mom'],['С папой','dad'],['Свой голос','agency']].forEach(([name,key])=>{let row=document.createElement('div');row.className='relation';let lab=document.createElement('label');let a=document.createElement('span');a.textContent=name;let b=document.createElement('span');b.textContent=story[key]+'%';lab.append(a,b);let meter=document.createElement('div');meter.className='relation-meter';let fill=document.createElement('i');fill.style.width=story[key]+'%';meter.append(fill);row.append(lab,meter);card.append(row)});let hint=document.createElement('p');hint.className='hint';hint.textContent='Показатели отражают только выборы этого героя в игре. Близость и самостоятельность могут расти одновременно.';card.append(hint);let bag=document.createElement('div');bag.className='card';let title=document.createElement('h3');title.textContent='Находки';let inv=document.createElement('div');inv.className='inventory';(story.inventory.length?story.inventory.slice(-8):['Пока пусто']).forEach(item=>{let chip=document.createElement('span');chip.textContent=item;inv.append(chip)});bag.append(title,inv);side.append(card,bag);return side}
function renderScene(){if(!story)return showIntro();if(story.phase==='ending')return showEnding();let scene=storyScenes[story.chapter],root=gameFrame();let title=document.createElement('div');title.className='story-title';let h=document.createElement('h2');h.textContent=scene.title;let ch=document.createElement('span');ch.textContent='Глава '+(story.chapter+1)+' / 8';title.append(h,ch);root.append(title);let pips=document.createElement('div');pips.className='chapter-pips';storyScenes.forEach((_,i)=>{let pip=document.createElement('i');if(i<=story.chapter)pip.className='done';pips.append(pip)});root.append(pips);let shell=document.createElement('div');shell.className='story-shell';let main=document.createElement('div');main.className='story-main';let world=document.createElement('div');world.className='world '+scene.bg;let tag=document.createElement('span');tag.className='scene-label';tag.textContent=scene.place+' · '+scene.time;world.append(tag,character('hero'),character(scene.npc));let hotspots=document.createElement('div');hotspots.className='hotspots';scene.objects.forEach((o,i)=>{let b=document.createElement('button');b.className='hotspot'+(story.seen.includes(i)?' seen':'');b.style.left=o.x+'%';b.style.top=o.y+'%';b.textContent=o.icon;b.setAttribute('aria-label','Осмотреть: '+o.label);b.onclick=()=>{if(!story.seen.includes(i)){story.seen.push(i);if(!story.inventory.includes(o.label))story.inventory.push(o.label);persistStory()}renderScene();let info=document.querySelector('#objectInfo');if(info)info.textContent=o.label+': '+o.detail};hotspots.append(b)});world.append(hotspots);main.append(world);let sceneCard=document.createElement('div');sceneCard.className='card scene-card';let intro=typeof scene.intro==='function'?scene.intro(story):scene.intro;say(sceneCard,'Рассказчик',intro);let npcText=typeof scene.line==='function'?scene.line(story):scene.line;say(sceneCard,scene.npc==='mom'?'Мама':scene.npc==='dad'?'Папа':'Ника',npcText);let info=document.createElement('div');info.id='objectInfo';info.className='scene-info';info.textContent=story.seen.length?'Предмет осмотрен. Теперь можно действовать.':'Нажми на предмет в сцене, чтобы узнать больше и открыть действия.';sceneCard.append(info);
 let prompt=document.createElement('div');prompt.className='scene-prompt';prompt.textContent='Что делает '+story.name+'?';sceneCard.append(prompt);let actions=document.createElement('div');actions.className='scene-actions';scene.choices.forEach((choice,i)=>{let b=document.createElement('button');b.textContent=choice.text;b.disabled=!story.seen.length||story.phase==='reply';b.onclick=()=>choose(i);actions.append(b)});sceneCard.append(actions);if(story.phase==='reply'){actions.hidden=true;let selected=scene.choices[story.decisions[story.chapter]];say(sceneCard,story.name,selected.text,true);say(sceneCard,scene.npc==='mom'?'Мама':scene.npc==='dad'?'Папа':'Ника',selected.reply);let adv=document.createElement('button');adv.className='primary scene-advance';adv.textContent=story.chapter===7?'Посмотреть финал →':'Следующая глава →';adv.onclick=advance;sceneCard.append(adv)}main.append(sceneCard);shell.append(main,relationCard());root.append(shell);let foot=document.createElement('p');foot.className='story-footnote';foot.textContent='Это вымышленная история. Выбор в игре ничего не отправляет родителям и не оценивает ваши отношения.';root.append(foot)}
function choose(i){if(story.phase==='reply')return;let choice=storyScenes[story.chapter].choices[i];story.decisions[story.chapter]=i;story.mom=clamp(story.mom+(choice.mom||0));story.dad=clamp(story.dad+(choice.dad||0));story.agency=clamp(story.agency+(choice.agency||0));if(choice.route)story.route=choice.route;story.phase='reply';persistStory();renderScene()}
function advance(){story.chapter++;story.seen=[];story.phase=story.chapter>=8?'ending':'explore';persistStory();renderScene()}
function showEnding(){let root=gameFrame();let box=document.createElement('div');box.className='story-ending';let star=document.createElement('span');star.className='eyebrow';star.textContent='Финал истории';let h=document.createElement('h2');h.textContent='Своя дорога, живая связь';let p=document.createElement('p');p.textContent=story.route==='move'?story.name+' начинает жизнь в новом городе. Мама и папа пока привыкают к переменам. У этой истории есть продолжение — звонки, встречи и новые договорённости.':story.route==='stay'?story.name+' остаётся в городе и выбирает свой проект. Географическая близость не отменяет собственного решения и новых границ.':story.name+' возвращается из ознакомительной поездки с большим количеством фактов. Решение можно принять позже, оставаясь автором своей жизни.';let p2=document.createElement('p');p2.textContent=story.mom>=60?'С мамой стало проще говорить о планах, даже когда мнения различаются.':'С мамой пока есть напряжение. Один разговор не обязан всё исправить; связь может меняться постепенно.';let note=document.createElement('p');note.className='story-footnote';note.textContent='Это финал сюжета, а не утверждение, что человек «сепарировался». В жизни отношения сложнее игровых показателей.';let btns=document.createElement('div');btns.className='story-credits';let again=document.createElement('button');again.className='primary';again.textContent='Прожить другой путь';again.onclick=()=>{localStorage.removeItem(STORY_KEY);story=null;renderGameHub();showIntro()};let hub=document.createElement('button');hub.className='secondary';hub.textContent='К другим играм';hub.onclick=showHub;btns.append(again,hub);box.append(star,h,p,p2,note,btns);root.append(box)}
document.querySelector('#startGame').onclick=()=>{story=loadStory();if(!story||story.phase==='ending')showIntro();else renderScene()};
renderGameHub();
